INSERT /* setUserWithdrawal */
  INTO TH_USWTHD (
       USER_NUMB
     , USER_IDHS
     , WTHD_TYPE
     , WTHD_RSON
     , RSON_CNTN
     , WTHD_STAT
     , REQU_DATE
     , DELT_DATE
     , PROC_DATE
     , ERRO_CNTN
) VALUES (
       #{userNumb}
     , #{userIdhs}
     , #{wthdType}
     , #{wthdRson}
     , #{rsonCntn,jdbcType=VARCHAR}
     , #{wthdStat}
     , CURRENT_TIMESTAMP
     , #{deltDate,jdbcType=TIMESTAMP}
     , #{procDate,jdbcType=TIMESTAMP}
     , #{erroCntn,jdbcType=VARCHAR}
)

/* uptReadingStatsPrivate */
INSERT INTO TM_USSETX (
            USER_NUMB
          , RSTA_YSNO
          , GOAL_YSNO
          , IMFD_YSNO
          , RPUB_YSNO
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{userNumb}
          , #{privateYsno}
          , #{privateYsno}
          , #{privateYsno}
          , #{privateYsno}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)
ON DUPLICATE KEY UPDATE
       RSTA_YSNO = VALUES(RSTA_YSNO)
     , GOAL_YSNO = VALUES(GOAL_YSNO)
     , IMFD_YSNO = VALUES(IMFD_YSNO)
     , RPUB_YSNO = VALUES(RPUB_YSNO)
     , UPDT_DATE = CURRENT_TIMESTAMP(6)

