DELETE /* delUserReplyLike */
  FROM TB_LIKEXX
 WHERE USER_NUMB = #{userNumb}
   AND TAGT_TYPE = #{likeTargetReply}

DELETE /* delComplaintResults */
  FROM TH_CMRSLT
 WHERE USER_NUMB = #{userNumb}
